        "content": "Õppeaine keskendub tagarakenduste arendamisele, kasutades Node.js-i ja TypeScripti. Kursusel omandatakse oskused serverirakenduste loomiseks ning objektorienteeritud programmeerimise (OOP) põhimõtete, nagu klassid, objektid, pärilus ja kapseldamine, rakendamiseks API-de arenduses. Õppijad õpivad looma hästi disainitud RESTful API-sid, järgides API disaini parimaid praktikaid, sealhulgas loogiliste ja intuitiivsete ressursside ja endpoint-ide loomist, kasutajasõbralike veateadete koostamist ja korrektsete vastuskoodide kasutamist.\n\nKursusel käsitletakse CRUD (Create, Read, Update, Delete) API-de loomise ja struktureerimise põhimõtteid, kasutades Expressi ja middleware’i. Olulisel kohal on autentimise ja autoriseerimise teemad, sealhulgas JWT-põhiste lahenduste rakendamine, sessioonipõhise ja sessioonivaba autentimise võrdlus ning API turvalisuse tagamine OWASP TOP10 juhiste alusel. Õppijad õpivad rakendama turvamehhanisme, nagu sisendi valideerimine, vigade käsitlemine, paroolide räsimine ja tundliku informatsiooni kaitse.\n\nLisaks omandatakse teadmised ja oskused API testimiseks ja dokumenteerimiseks, kasutades kaasaegseid tööriistu, nagu Jest, Mocha, Supertest ja Swagger. Kursuse käigus pööratakse erilist tähelepanu versioonihalduse (nt Git ja GitHub) kasutamisele meeskonnatöö ja projektide tõhustamiseks. Kursuse praktilise osana loovad õppijad täielikult funktsionaalse API, mis arvestab kõiki kursuse jooksul käsitletud punkte, sealhulgas OOP-põhist arhitektuuri, turvalisuse nõudeid, autentimist ja autoriseerimist, dokumenteerimist ning testimist.",
