        "content": "Õppeaine annab tervikliku ülevaate tarkvaraarenduse alustest, hõlmates tarkvara olemust, erinevaid tarkvaratüüpe ning tarkvara arendusprotsesside ja metoodikate põhimõtteid. Kursus tutvustab funktsionaalsete ja mittefunktsionaalsete nõuete defineerimist, tarkvara litsentsimise tüüpe ning nende praktilist rakendamist tarkvaraprojektides. Õppijad omandavad teadmised tarkvara arendusprotsessidest ja nende etappidest, sealhulgas SDLC (Software Development Life Cycle) ning agiilsete meetodite eelistest ja kasutusvõimalustest. Erilist rõhku pannakse tarkvara arhitektuuri põhimõtete mõistmisele ning arendusmeeskonna rollide ja ülesannete analüüsimisele. Kursus arendab praktilisi oskusi versioonihalduse tööriistade, nagu Git ja GitHub, kasutamisel meeskonnatöös (nt pull request-id, koodi ülevaatused, harude haldamine ja projektihaldus). Lisaks käsitletakse heade arendustavade järgimist, sealhulgas koodi dokumenteerimist, kvaliteedi tagamise meetodeid ja tööriistu. Kursuse käigus tutvutakse ajahalduse põhimõtetega, et arendada tõhusust tarkvaraarenduse protsessides.",
