        "id": 9,
        "semester": 2,
        "order": 3,
        "url": "https://docs.google.com/document/d/1C51xaLBfMU9Q-EgiGdBA8kk2hJFHX2hukBWUO0zqkto/edit?usp=drive_link",
        "name": "Eesrakenduste arendamine",
        "module": 3,
        "required": true,
        "prerequisites": [
          3,
          5
        ],
        "credits": 6,
        "content": "Õppeaine annab tervikliku ülevaate eesrakenduste arenduse alustest, hõlmates nii teoreetilisi kui ka praktilisi teadmisi veebiarenduse valdkonnast. Kursuse esimeses osas keskendutakse HTML-i ja CSS-i põhialustele, tutvustades HTML-i struktuuri, semantiliste elementide kasutamist ligipääsetavuse ja SEO parandamiseks ning CSS-i parimaid praktikaid kaasaegsete veebilahenduste loomiseks.\n    Erilist tähelepanu pööratakse kohanduva (responsive) disaini põhimõtetele, mobiilseadmete toe tagamisele, CSS-i raamistikude (nt Bootstrap ja Tailwind) ja eelprotsessorite (nt SASS, LESS) kasutamisele.\n    Samuti käsitletakse veebiarenduse olulisi aspekte nagu ligipääsetavus (WCAG standardid) ja koodi valideerimine, kasutades tööriistu, mis aitavad järgida rahvusvahelisi standardeid.\n\nJavaScripti käsitlemisel tutvustatakse keele süntaksit, andmetüüpe, koodi struktureerimise meetodeid, DOM-i manipuleerimist, sündmuste käsitlemist ning väliste API-de andmete töötlemist ja kuvamist.\n\nÕppeaine oluline osa on versioonihaldus ja koodihaldussüsteemide kasutamine. Õppijad omandavad oskused kasutada Git-i ja GitHubi koodi haldamiseks, sealhulgas koostöö ja projekti jälgimise tööriistu. Kursus hõlmab ka CSS- ja JavaScript-raamistike rakendamist veebirakenduste arendamisel, et kiirendada töövooge ja parandada loodud lahenduste kvaliteeti.\n\nÕppeaine raames rakendavad üliõpilased teooriat praktiliste projektide kaudu, luues ja optimeerides kaasaegseid eesrakendusi, mis vastavad veebiarenduse standarditele ja kasutajakogemuse parimatele praktikatele.",
        "objective": "Eesmärk on anda üliõpilastele põhjalikud teadmised ja praktilised oskused kaasaegsete eesrakenduste arendamiseks, hõlmates HTML-i, CSS-i ja JavaScripti kasutamist, CSS-i raamistike rakendamist, ning veebilahenduste loomisel ligipääsetavuse ja valideerimise standardite järgimist. Lisaks arendada oskusi projekti dokumenteerimisel ja versioonihaldustööriistade (nt Git, GitHub) tõhusal kasutamisel, et toetada koostööd ja projekti jätkusuutlikkust.",
