        "content": "Õppeaine keskendub dünaamiliste veebilehtede loomise ja serveripoolse arenduse põhialustele. Kursusel käsitletakse serveripoolse renderdamise (Server-Side Rendering, SSR) põhimõtteid ja monoliitset arhitektuuri, kus frontend ja backend on integreeritud ühtseks lahenduseks. Läbi praktiliste ülesannete omandatakse oskused Node.js-i abil serveripoolse rakenduse loomiseks ja sisu haldamiseks, kasutades nii Node.js-i sisseehitatud mooduleid, kui ka kolmanda osapoole mooduleid (nt Express). Samuti käsitletakse andmete pärimist välistest API-dest, nende töötlemist JSON-formaadis ja andmete kuvamist serveripoolsete mallide ja mallimootorite (EJS, Pug, Handlebars) abil. Kursus pakub ka põhjaliku ülevaate HTTP protokollist, selle meetoditest (GET, POST, PUT, DELETE) ja vastuskoodidest (nt 200, 404, 500), süvenedes request-response tsükli tööpõhimõtetesse ja nende rakendamisse Node.js-is. Lisaks eelnevale pööratakse tähelepanu ka veebilehe turvalisusele lähtudesd OWASP TOP10 nimekirjast. Kursuse käigus pööratakse erilist tähelepanu dokumenteerimisele, ning versioonihalduse (nt Git ja GitHub) kasutamisele arendusprojektide tõhustamiseks ja meeskonnatöö toetamiseks.",
        "objective": "Õppeaine eesmärk on anda üliõpilastele põhjalikud teadmised ja praktilised oskused dünaamiliste veebirakenduste loomiseks, keskendudes serveripoolse renderdamise (SSR) ja monoliitse arhitektuuri rakendamisele. Kursus arendab oskusi kasutada Node.js-i ja selle mooduleid (sh Express), luua turvalisi ja jätkusuutlikke veebirakendusi, töötada välistest API-dest pärinevate andmetega ning rakendada parimaid praktikaid versioonihalduse ja dokumenteerimise alal, toetades seeläbi arendusprotsesside kvaliteeti ja meeskonnatööd.",
