        "credits": 3,
        "content": "Õppeaine annab põhjaliku ülevaate videomängude disainist ja arendamise alustest, keskendudes nii teoreetilistele kui ka praktilistele oskustele. Kursus algab arvutimängude ajaloo ja mänguplatvormide tüüpide tutvustamisega, et luua alus mängudisaini analüüsile ja loomeprotsessile. Õppeprotsessi käigus analüüsitakse mängude žanre ja uuritakse mängude põhikomponente, sealhulgas mängumehaanika (keskkond, objektid, interaktsiooni vormid ja reeglid), esteetika (visuaalne, heliline ja taktiilne) ning narratiivi rolli mängukogemuse kujundamisel. Pööratakse tähelepanu mängijate psühholoogia mõistmisele ja sellega arveestamisele, et luua kaasahaaravaid ja motiveerivaid mängukogemusi. Kursus keskendub mängukavandi põhikomponentidele ja nende dokumenteerimisele. Õppijad koostavad mängudisaini dokumentatsiooni, mis kajastab mängu kavandi kõiki olulisi aspekte, ning arendavad rühmatööna mängu prototüübi. Praktilise osana viivad õppijad läbi testimise ja analüüsi, et hinnata valminud mängu kvaliteeti ja mängitavust. Õppetöö toimub loengute, seminaride ja praktiliste töötubade vormis, pakkudes õppijatele nii loovaid kui ka analüütilisi väljakutseid. Kursus arendab oskusi ja teadmisi, mis on vajalikud mängudisaini protsessi igas etapis, alates ideest kuni valmis prototüübini. Õppijad komplekteerivad 4-5 liikmelised rühmad ja jagavad rühmasiseselt tööülesanded. Rühmatöö raames koostavad õppijad etteantud juhendi alusel mängudisaini dokumentatsiooni ja loovad mängu prototüübi. Dokumentatsioon ja prototüüp esitatakse arvestusel. Õppijad kasutavad kursuse käigus loodud dokumentatsiooni ja muude dokumentide talletamiseks ja haldamiseks versioonihalduse tööriistu (nt Git ja GitHub).",
        "objective": "Anda ülevaade mängudisaini alustest ning toetada teadmiste ja oskuste kujunemist, mis võimaldavad üliõpilasel osaleda mängukavandi loomise protsessis. Kursus keskendub mängumehaanika, esteetika ja narratiivi tasakaalustamisele, samuti mängijate psühholoogia tundmisele ja mängudisaini dokumentatsiooni koostamisele. Kursus arendab loovust ja analüütilist mõtlemist, mis on vajalikud kaasahaaravate ja kvaliteetsete mängukogemuste loomiseks.",
