        "credits": 6,
        "content": "Õppeaine annab põhjalikud teadmised ja praktilised oskused andmebaaside projekteerimise, haldamise ja optimeerimise valdkonnas, keskendudes nii relatsioonilistele kui ka kaasaegsetele NoSQL ja hübriidlahendustele. Kursus tutvustab andmebaaside arhitektuuri, põhimõisteid ja arengusuundi, andes kindla aluse andmemudelite loomisel ja nende seostamisel praktiliste vajadustega. Andmebaaside projekteerimise osas omandatakse oskused koostada andmemudeleid ja ER-diagramme, määrata võtmeid ja seoseid ning rakendada normaliseerimist, et tagada andmestruktuuride efektiivsus ja kvaliteet. SQL-i aluseid ja keerukamaid käske õppides saavad üliõpilased teadmised, kuidas luua, hallata ja pärida andmeid tõhusalt, kasutades nii lihtsaid kui ka keerukaid päringuid, sh aknafunktsioone ja agregeerimisfunktsioone. Andmebaaside optimeerimise ja skaleerimise teemades käsitletakse indekseid, päringute optimeerimist ning skaleeritavuse ja kättesaadavuse tagamist, sealhulgas replikatsiooni kasutamist. Kursusel pööratakse erilist tähelepanu andmebaaside administreerimisele, sealhulgas varundamisele, taasteplaanidele, kasutajate haldusele ja turvalisusele. Praktilised teemad hõlmavad salvestatud protseduuride, funktsioonide ja päästikute loomist ning nende rakendamist, et suurendada andmebaaside funktsionaalsust ja automatiseerida protsesse. Kursus sisaldab ka transaktsioonide haldamise ja veahaldustehnikate tutvustamist, et tagada süsteemi töökindlus ja andmete terviklikkus.",
        "objective": "Õppeaine eesmärk on anda üliõpilastele põhjalikud teadmised ja praktilised oskused andmebaaside projekteerimisel, haldamisel ja optimeerimisel. Kursus keskendub relatsiooniliste andmebaaside alustele ja kaasaegsetele andmebaasilahendustele, sealhulgas SQL-i kasutamisele, andmestruktuuride efektiivsuse tagamisele, päringute optimeerimisele, skaleeritavusele ja turvalisusele. Samuti arendab õppeaine oskusi salvestatud protseduuride, funktsioonide ja päästikute loomisel, andmebaaside administreerimisel ning andmete varundamise ja taasteplaanide rakendamisel, et toetada praktiliste probleemide lahendamist ja süsteemide töökindlust.",
