        "content": "Õppeaine annab ülevaate diskreetse matemaatika alustest ja selle olulisusest IT-valdkonnas. Kursusel käsitletakse hulgateooriat, loogikat, graafe, kombinatoorikat, tõenäosust, rekursiooni ja arvuteooriat. Õppijad uurivad, kuidas diskreetse matemaatika põhimõtted toetavad programmeerimist ja algoritmilist mõtlemist, ning õpivad neid rakendama praktiliste probleemide lahendamisel.\n\nTeemade hulka kuuluvad hulkade manipuleerimine, loogiliste avaldiste lihtsustamine, graafi algoritmid (nt DFS, BFS), permutatsioonide ja kombinatsioonide rakendused, tõenäosuse ja juhuslike protsesside modelleerimine, rekursioon ning algoritmide keerukuse analüüs. Lisaks käsitletakse moodularitmeetikat ja diskreetseid aritmeetilisi meetodeid, sealhulgas nende kasutamist krüptograafias. Kursus rõhutab matemaatiliste kontseptsioonide ja programmeerimispõhise lähenemise integreerimist erinevate IT-valdkonna probleemide lahendamisel.",
        "objective": "Eesmärk on anda õpilastele arusaam diskreetse matemaatika alustest ja selle rakendustest IT-valdkonnas. Kursus toetab matemaatiliste teadmiste rakendamist praktiliste probleemide lahendamisel, arendades oskust integreerida diskreetset matemaatikat programmeerimisse, algoritmide ja andmestruktuuride kujundamisse.",
