        "content": "Õppeaine annab põhjaliku ülevaate serverihalduse rollist ja tähtsusest veebiarenduses, keskendudes praktiliste oskuste arendamisele füüsiliste ja virtuaalserverite, konteinerite ja orkestreerimislahenduste haldamisel. Kursusel käsitletakse serverite ja virtuaalmasinate loomise ning haldamise põhimõtteid, sealhulgas konteineriseerimise tehnoloogiaid nagu Docker ja orkestreerimistööriistu nagu Kubernetes. Õppijad õpivad rakendama CI/CD töövoogusid automatiseeritud testimise ja deployment'i tõhustamiseks, kasutades tööriistu nagu GitHub Actions ja Jenkins. Kursus hõlmab rakenduste logimise ja monitoorimise aluseid, sealhulgas struktureeritud logimist (nt Winston, Logstash) ning monitoorimistööriistu nagu Prometheus ja Grafana. Samuti käsitletakse serverihalduse turvalisuse aspekte, sealhulgas tulemüüri seadistamist, SSL-sertifikaatide kasutamist ning tundlike andmete ja võtmete haldamist. Õppijad arendavad oskusi veebirakenduste deploy meetodite rakendamiseks, sh automatiseeritud ja käsitsi deploy protsessid.",
