        "content": "Õppeaine annab süsteemse ülevaate kaasaegsest andmeturbest ja krüptograafiast. Kursusel käsitletakse turvaeesmärke, ohte, riske ja nende analüüsi ning turvapoliitikate ja -strateegiate loomist. Õppijad tutvuvad mitmekasutajasüsteemide turvalisusega, sealhulgas juurdepääsukontrollide (DAC, MAC), turvatasemete ja tulemüüride kasutamisega. Kursus hõlmab autentimismeetodeid ja identiteedihaldust, sealhulgas paroolisüsteeme, NIS(+), Kerberost, Active Directory’t, LDAP katalooge ning single sign-on lahendusi. Samuti keskendutakse turvalisele programmeerimisele, käsitledes OWASP TOP 10 haavatavusi, puhvri ületäitumist ja koodiga seotud ohte erinevates programmeerimiskeeltes (C/C++, Java, PHP, SQL). Lisaks käsitletakse rünnakute avastamist ja tõrjumist seire, IDS (Intrusion Detection Systems) ja logimise abil. Kursusel tutvutakse seadusandlike raamistikudega, nagu ISKE, ning käsitletakse intsidentide haldust ja taasteplaane turvaprobleemide lahendamiseks.",
