        "credits": 10,
        "content": "Praktika III eesmärk on toetada üliõpilaste iseseisva töö ja projektijuhtimise oskuste arendamist, pakkudes võimalust rakendada varasemalt õpitud teadmisi ning oskusi kas ettevõttepraktika või individuaalprojekti kaudu. Praktikat saab sooritada kahel viisil: Ettevõttepraktika: Üliõpilane osaleb praktikandina IT-ettevõttes või asutuse IT-osakonnas, tutvudes ettevõtte struktuuri, töökorralduse ja infotehnoloogilise baasi toimimisega. Praktika jooksul täidab üliõpilane ettevõtte juhendaja poolt määratud ülesandeid, mis toetavad tema erialaste oskuste arengut ja praktiliste tööprotsesside mõistmist. Individuaalprojekt: Üliõpilane arendab iseseisvalt või meeskonnatöös mõnda tarkvaraprojekti, mis võib olla varasemalt alustatud, täiesti uus või osa vabavaralisest projektist. Projekti fookus võib olla seotud tarkvaraarenduse, andmeanalüüsi, süsteemihalduse või muu IT-alase teemaga. Mõlemal juhul on praktika vältel oluline regulaarne dokumenteerimine praktikapäeviku vormis, kus kajastatakse tehtud tööde sisu, eesmärke ja ajakulu. Olulisel kohal on ka projekti dokumentatsiooni koostamine, et tagada tööprotsessi läbipaistvus ja hilisem analüüs. Praktika lõppeb kokkuvõtva aruande ja projekti esitlusega, kus üliõpilane reflekteerib oma õpikogemust ja saadud tulemusi.",
        "objective": "Eesmärk on pakkuda üliõpilastele võimalusi õppetöö käigus omandatud teadmiste ja oskuste rakendamiseks ning kinnistamiseks praktilises keskkonnas. Praktika arendab analüüsi-, probleemilahendus- ja ajaplaneerimise oskusi, toetades üliõpilaste professionaalset arengut kas ettevõttepraktika või individuaalse projekti kaudu. Samuti soodustab praktika dokumenteerimise, versioonihalduse ja tööprotsessi läbipaistvuse oskuste arendamist.",
